INSERT INTO aml_alerts (id, statement_id, rule_code, severity, title, description, trigger_amount, partner_name, is_str_reported, str_report_id) VALUES ('aml_alert_2', NULL, 'AML-PASSTHROUGH', 'CRITICAL', 'Dòng tiền chuyển tiếp siêu tốc (Rapid Pass-Through)', 'Tiền vào tài khoản và rút ra ví điện tử 99.9% trong vòng dưới 10 phút. Đối tác liên quan: Vietnam Airlines', 2650000000, 'Vietnam Airlines', 1, 'STR-NHNN-2026-902');
INSERT INTO aml_alerts (id, statement_id, rule_code, severity, title, description, trigger_amount, partner_name, is_str_reported, str_report_id) VALUES ('aml_alert_3', NULL, 'AML-NIGHT-VELOCITY', 'HIGH', 'Tần suất giao dịch bất thường ngoài giờ (Night Velocity)', 'Giao dịch phát sinh liên tiếp từ 01:00 - 04:00 sáng với giá trị lớn hơn 50M VND. Đối tác liên quan: Gemadept', 1475000000, 'Gemadept', 1, 'STR-NHNN-2026-903');
